def outside_managed_bytes(value: bytes) -> bytes:
    begin = value.index(POLICY_BEGIN.encode("utf-8"))
    end = value.index(POLICY_END.encode("utf-8"), begin) + len(POLICY_END.encode("utf-8"))
    return value[:begin] + value[end:]

